import { EixoBNCC } from '@prisma/client';

type Raw = { level:string; levelName:string; stage:string; stageName:string; yearStart:number|null; yearEnd:number|null; code:string; axis:EixoBNCC|null; description:string; explanation:string; examples:string[] };
export type BnccSkillSeed = Pick<Raw, 'code' | 'axis' | 'description' | 'explanation' | 'examples'>;
export type BnccStageSeed = { code: string; name: string; yearStart: number | null; yearEnd: number | null; skills: BnccSkillSeed[] };
export type BnccLevelSeed = { code: string; name: string; stages: BnccStageSeed[] };
const raw = JSON.parse(Buffer.from('','base64').toString('utf8')) as Raw[];
type StageMetadata = Pick<BnccStageSeed, 'name' | 'yearStart' | 'yearEnd'>;

/**
 * The source headings identify the learning stage through the BNCC code.  Do
 * not use their display text as a database key: headings such as "Ano 1"
 * previously lost their ordinal during parsing and made every EF stage share
 * the same name.  These canonical values satisfy the Prisma unique constraint
 * on (nivelEnsinoId, nome) and the PostgreSQL year-range trigger.
 */
function canonicalStage(level: string, code: string): StageMetadata {
  if (level === 'EDUCACAO_INFANTIL' && code === 'EI') {
    return { name: 'Educação Infantil', yearStart: null, yearEnd: null };
  }

  if (level === 'ENSINO_FUNDAMENTAL') {
    const singleYear = /^EF0([1-9])$/.exec(code);
    if (singleYear) {
      const year = Number(singleYear[1]);
      return { name: `${year}º ano`, yearStart: year, yearEnd: year };
    }
    if (code === 'EF15') return { name: '1º ao 5º ano', yearStart: 1, yearEnd: 5 };
    if (code === 'EF69') return { name: '6º ao 9º ano', yearStart: 6, yearEnd: 9 };
  }

  if (level === 'ENSINO_MEDIO' && code === 'EM13') {
    return { name: '1º ao 3º ano', yearStart: 1, yearEnd: 3 };
  }

  throw new Error(`Etapa BNCC não reconhecida: ${level}/${code}`);
}

export const bnccCatalog: BnccLevelSeed[] = Object.values(raw.reduce((levels, item) => {
  const level = levels[item.level] ??= { code: item.level, name: item.levelName, stages: {} as Record<string, BnccStageSeed> };
  const metadata = canonicalStage(item.level, item.stage);
  const stage = level.stages[item.stage] ??= { code: item.stage, ...metadata, skills: [] };
  stage.skills.push({ code: item.code, axis: item.axis, description: item.description, explanation: item.explanation, examples: item.examples });
  return levels;
}, {} as Record<string, { code: string; name: string; stages: Record<string, BnccStageSeed> }>)).map(level => ({ ...level, stages: Object.values(level.stages) }));
